import json
import pathlib

import numpy
import pandas
import pytest

import metafopy

# generated by src/tests/r/generate_formula_rank.R
REFERENCE = json.loads((pathlib.Path(__file__).parent / 'reference' / 'formula_rank.json').read_text())

RTOL = 1e-6
# the location-scale fit is found by an optimiser, so its estimates agree with R's only to the optimiser's tolerance: a full-rank scale model
# on the same data differs from R by as much, and the standard errors of alpha (from a numerical Hessian) by more
OPTIM = 1e-4
OPTIM_HESSIAN = 1e-2


def frame(key: str) -> pandas.DataFrame:
    return pandas.DataFrame(REFERENCE[key])


def close(actual: numpy.typing.ArrayLike, expected: list[float], rtol: float) -> None:
    numpy.testing.assert_allclose(numpy.asarray(actual, dtype=float), numpy.asarray(expected, dtype=float), rtol=rtol)


def test_rma_uni_drops_redundant_column_as_r() -> None:
    expected = REFERENCE['uni']
    with pytest.warns(UserWarning, match=expected['warning']):
        res = metafopy.rma_uni('yi', 'vi', mods='~ deltype:outcome', data=frame('data'), method='FE')
    assert tuple(res.coef_names) == tuple(expected['names'])
    close(res.beta, expected['beta'], RTOL)
    close(res.se, expected['se'], RTOL)


def test_rma_mv_drops_redundant_column_as_r() -> None:
    expected = REFERENCE['mv']
    with pytest.warns(UserWarning, match=expected['warning']):
        res = metafopy.rma_mv('yi', 'vi', mods='~ deltype:outcome', random='~ 1 | id', data=frame('data'))
    assert tuple(res.coef_names) == tuple(expected['names'])
    close(res.beta, expected['beta'], RTOL)
    close(res.se, expected['se'], RTOL)


def test_scale_model_drops_redundant_column_as_r() -> None:
    expected = REFERENCE['ls']
    with pytest.warns(UserWarning, match=expected['warning']):
        res = metafopy.rma_uni('yi', 'vi', mods='~ year', scale='~ deltype:outcome', data=frame('data_ls'))
    assert tuple(res.coef_names) == tuple(expected['names'])
    assert tuple(res.alpha_names) == tuple(expected['alpha_names'])
    close(res.beta, expected['beta'], OPTIM)
    close(res.se, expected['se'], OPTIM)
    close(res.alpha, expected['alpha'], OPTIM)
    close(res.se_alpha, expected['alpha_se'], OPTIM_HESSIAN)
